import type { RichArticle } from './rich-articles';
type Core=readonly[string,string,string,string,string,string,string];
type Topic={core:Core;situation:string;analysis:string;closing:string};
const topics:Topic[]=[
{core:['outsourced-account-management-pilot-scorecard','Outsourced account management pilot scorecard','client-onboarding-coordination','evaluate a first account-management pilot before expanding the portfolio','account cohort, delegated tasks, baseline, service measure, exception, review sample, owner decision, and expansion gate','A busy first fortnight is not evidence that a pilot is ready to scale.','2026-08-31-handoff-shadow-review.png'],situation:'A ten-account pilot produces many completed follow-ups, but two records lack source links and one client promise has no decision owner.',analysis:'Design the scorecard around the decision the pilot must support. Freeze the account cohort and approved task list before work begins, then compare timeliness, factual accuracy, exception handling, access discipline, and reviewer effort with a stated baseline. Sample both normal work and difficult cases; a completion total can hide rework or unauthorized judgment. Track owner interventions separately so apparent productivity does not depend on invisible management effort. Expansion should require observable evidence for each gate, not an average that allows a serious control failure to disappear.',closing:'The accountable manager records expand, extend, narrow, or stop, with reasons and the next bounded cohort.'},
{core:['client-onboarding-stalled-dependency-recovery','Client onboarding stalled dependency recovery','client-onboarding-coordination','recover a stalled onboarding plan without inventing dates or bypassing approvals','blocked milestone, dependency, authoritative source, request history, impact, workaround boundary, owner, next check, and recovery proof','A launch checklist can appear active while every remaining item depends on one unanswered access decision.','2026-08-31-stakeholder-absence-plan.png'],situation:'Training is complete, but the production workspace is unavailable and the client contact who requested access is away.',analysis:'Separate activity from progress. Identify the earliest blocked milestone, the exact dependency, who has authority to resolve it, and which downstream dates are genuinely affected. Confirm whether a safe sandbox, approved sample, or documentation review can continue without implying production readiness. Do not obtain access through another user or convert an estimated response into a client commitment. Maintain a short request history so escalation reflects elapsed consequence rather than message volume. When the dependency clears, revalidate assumptions and recalculate the sequence from evidence instead of forcing the original dates.',closing:'Close recovery only after the dependency is verified, affected milestones are re-planned, and the client receives approved dates.'},
{core:['account-portfolio-segmentation-rules','Account portfolio segmentation rules','account-health-monitoring','segment an account portfolio with transparent workload and risk rules','account population, segmentation purpose, input definition, cutoff, exception, capacity effect, reviewer, refresh event, and decision','A high-value label does not tell an account manager which work should happen today.','2026-08-31-portfolio-exception-budget.png'],situation:'Revenue, renewal proximity, unresolved service issues, and stakeholder activity point to different priority orders.',analysis:'Begin with the operational decision segmentation will change: review cadence, coverage, escalation, or staffing. Define every input, freeze its cutoff, and retain missing values as unknown rather than favorable. Avoid a universal tier that combines commercial importance and service risk into an unexplained score. Show separate dimensions when they lead to different actions. Test edge cases, including a small account with a serious unresolved issue and a large account with stable delivery. Compare the resulting workload with actual capacity so a theoretically correct tier does not create an impossible contact plan.',closing:'Approve rules, exceptions, owners, and refresh triggers; preserve prior tiers so changes remain explainable.'},
{core:['renewal-contact-authority-confirmation','Renewal contact authority confirmation','renewal-administration','confirm who may receive, discuss, and decide renewal information','account, contact, role, authority source, communication purpose, channel, effective date, conflict, owner, and confirmation','A familiar stakeholder may coordinate meetings without authority to approve a renewal.','2026-08-31-renewal-evidence-freeze.png'],situation:'The usual contact asks for pricing while the contract record names a procurement owner who has not joined recent reviews.',analysis:'Map communication access and decision authority separately. Record who may receive operational material, who can discuss commercial options, who signs, and which source supports each conclusion. Titles and historical behavior are clues, not proof. Escalate conflicts between CRM notes, contract records, and current client instructions before sending restricted material or treating informal agreement as approval. Keep the account specialist focused on evidence preparation and scheduling; pricing, terms, and legal interpretation remain with authorized owners. Recheck authority after reorganizations, absences, and contact changes.',closing:'The renewal record closes this check with a dated source, approved recipients, unresolved conflicts, and the next reconfirmation event.'},
{core:['qbr-action-decision-trace','QBR action and decision trace','customer-qbr-preparation','connect each QBR discussion to its evidence, decision, owner, and follow-up','agenda item, source evidence, discussion note, decision, condition, action, owner, due event, and confirmation','A polished QBR deck is incomplete when nobody can distinguish a discussion from a decision.','2026-08-31-client-metric-definition-card.png'],situation:'The client supports exploring a workflow change, but the recap says the change was approved for next month.',analysis:'Create the trace from agenda item to evidence, discussion, decision, and action. Quote qualified language such as explore, consider, or approve because each creates a different obligation. Capture conditions and dissent rather than compressing them into a positive summary. Assign preparation work without implying authority to make the underlying commercial, security, or scope decision. Send a bounded confirmation that allows the client to correct the record, and link later evidence to the original item. Reconcile open actions at the next review instead of copying them forward without status.',closing:'Closure requires decision confirmation or an explicit no-decision state, plus evidence for every completed action.'},
{core:['crm-duplicate-account-merge-control','CRM duplicate account merge control','crm-account-maintenance','merge duplicate account records without losing history, ownership, or automation context','candidate records, match evidence, authoritative identity, field winner, relationship, automation, owner, rollback, and verification','Two similar company names are not enough evidence to merge account histories.','2026-08-31-crm-correction-provenance-log.png'],situation:'One record owns open opportunities while another contains support history and a recently updated client contact.',analysis:'Treat the merge as a controlled data change. Confirm the legal or operational identity using approved sources, identify the surviving record, and decide field precedence one field at a time. Inventory relationships, permissions, workflows, integrations, reports, and external identifiers before changing anything. Export or preserve a permitted rollback record according to retention rules. Route ambiguous ownership, privacy, and financial fields to their accountable owners. After the merge, test linked work, reporting totals, notification recipients, and automation behavior; a clean screen can still hide broken references.',closing:'Record the approved match, field decisions, change evidence, post-merge tests, and any residual correction queue.'},
{core:['client-response-coverage-schedule','Client response coverage schedule','client-request-routing','set response coverage that distinguishes acknowledgement, ownership, and resolution','channel, coverage window, request class, acknowledgement target, owner assignment, decision boundary, exception route, handoff, and evidence','Always available is not an operating rule and can create unsupported expectations.','2026-08-31-client-silence-follow-up-rule.png'],situation:'A Philippines-based account support shift overlaps part of the client day, while commercial and technical owners work different hours.',analysis:'Map the actual channels and coverage windows before promising a response pattern. Define acknowledgement, triage, owner assignment, progress update, and resolution separately. A support specialist may confirm receipt and collect evidence without committing to a fix or commercial outcome. Provide rules for requests received near shift changes, channel outages, holidays, and urgent safety or security concerns. Test the schedule using realistic examples and name the next reachable decision owner. Publish wording that describes what the client can expect without pretending every request has the same consequence.',closing:'Approve the schedule, client-facing wording, exception contacts, and periodic review based on observed demand.'},
{core:['account-manager-leave-coverage-plan','Account manager leave coverage plan','implementation-handoff-support','prepare temporary account coverage without copying excessive access or private context','covered accounts, essential work, temporary owner, access need, client expectation, open decision, escalation path, return handback, and revocation','Calendar forwarding alone does not transfer account context or decision authority.','2026-08-31-handoff-shadow-review.png'],situation:'An account manager will be away during two client reviews and a renewal evidence deadline.',analysis:'Build temporary coverage from the account obligations that fall inside the absence, not from a wholesale copy of the person’s workspace. Identify essential contacts, open commitments, approved messaging, access needed, and decisions that must remain with another accountable owner. Keep personnel-sensitive notes and unrelated accounts out of the handoff. Rehearse one client update and one exception route before leave begins. Tell affected clients only what is necessary and approved. On return, reconcile actions, new commitments, and unresolved questions before revoking temporary permissions.',closing:'The handback closes when records are reconciled, clients have continuity, and temporary access is removed or reapproved.'},
{core:['client-complaint-acknowledgement-playbook','Client complaint acknowledgement playbook','customer-feedback-administration','acknowledge a client complaint without prejudging facts, liability, or remedy','complaint source, client wording, affected service, immediate need, evidence owner, response owner, update time, escalation, and receipt','A fast apology can still be harmful if it admits an unverified cause or promises an unauthorized remedy.','2026-08-31-escalation-audience-map.png'],situation:'A client reports repeated missed updates and asks for a credit before the activity record has been reviewed.',analysis:'Preserve the client’s words and acknowledge the impact they describe without asserting an unverified cause. Separate immediate safety or continuity needs from investigation, contractual interpretation, and remedy. State what will happen next, who owns the response, and when the client will receive an update; do not promise a final answer at that time unless it is realistic. Gather the relevant messages, service records, and commitments with a defined cutoff. Route credits, legal language, and material scope questions to authorized owners while the account specialist maintains the communication record.',closing:'Closure links the acknowledged complaint to findings, approved response, client receipt, corrective actions, and a reopen path.'},
{core:['service-credit-request-routing','Service credit request routing','escalation-coordination','route a service-credit request with complete facts and strict commercial authority','request wording, agreement source, service event, affected period, evidence, calculation input, commercial owner, client update, and disposition','A client request for a credit is not approval, and an internal estimate is not an offer.','2026-08-31-escalation-audience-map.png'],situation:'The client links a missed deliverable to a monthly fee and asks the account manager to confirm the amount today.',analysis:'Create a routing packet without interpreting the agreement or negotiating. Preserve the request, affected service and period, relevant delivery evidence, prior communications, and the exact contract source for qualified review. Separate factual calculations from eligibility and commercial discretion. Keep provisional numbers internal unless an authorized owner approves their use. Acknowledge receipt with a truthful decision timeline and avoid language that accepts liability. Track dependencies such as incident findings, invoice status, or required approvals so the client update reflects what is actually pending.',closing:'Record the authorized disposition, approved wording, communication proof, financial-system follow-through, and any corrective work.'},
{core:['client-account-offboarding-closure-checklist','Client account offboarding closure checklist','contract-milestone-tracking','close an account relationship without losing commitments, records, access, or ownership','end condition, open commitment, deliverable, record owner, retention rule, access, automation, client confirmation, and closure proof','A contract end date does not automatically close open work or revoke every connected system path.','2026-08-31-client-commitment-sunset-review.png'],situation:'Final deliverables are accepted, but shared folders, scheduled reports, and two unanswered client questions remain active.',analysis:'Translate the approved end condition into an operational sequence. Inventory open commitments, deliverables, invoices or commercial questions, records requiring retention, access grants, integrations, scheduled messages, and contact routing. Assign each item to the owner with authority to decide its disposition. Avoid deleting evidence or revoking access before required transfer and retention checks; equally, do not leave convenience access indefinitely. Provide the client with an approved summary of completed transfers and remaining obligations. Verify automation stops and permission changes from source systems.',closing:'Final closure requires evidence for disposition, transfer, retention, access removal, client communication, and residual ownership.'},
{core:['account-review-data-cutoff-reconciliation','Account review data cutoff reconciliation','account-reporting','reconcile late and changing data before an account review','report purpose, population, cutoff, late record, correction rule, materiality, narrative effect, owner, and version','Refreshing a dashboard minutes before a review can make the slides and spoken conclusions disagree.','2026-08-31-client-metric-definition-card.png'],situation:'A late support export changes the open-item count after the client deck has entered approval.',analysis:'Freeze the population, source versions, and cutoff used for the review. Log every late or corrected record with its effect on measures and narrative claims. Apply a predefined materiality and correction rule instead of choosing changes based on whether they improve the story. Minor items may enter a dated addendum; material changes may require reapproval or postponement. Preserve the earlier version and tell reviewers which one controls. During the meeting, distinguish results through the cutoff from events that occurred later so discussion does not rewrite the reporting period.',closing:'Reconcile the delivered version, client-facing correction if needed, next-period opening balance, and source refresh rule.'},
];
const deepDive:Record<string,[string,string]>={
'outsourced-account-management-pilot-scorecard':[
`Consider a pilot covering ten accounts for two weeks. The delegated scope includes meeting scheduling, approved follow-up, CRM notes, and preparation of the weekly risk list. Before launch, record the prior late-follow-up rate, the expected review sample, and which decisions remain with the internal account owner. During the pilot, count accepted outputs separately from returned work. A follow-up sent on time but based on an outdated contact record is not a clean success. Neither is a correct draft that required an undocumented manager rewrite. The scorecard should reveal both cases and show whether the operating instructions or the execution caused the problem.`,
`At the expansion review, avoid reducing the evidence to one percentage. Timeliness, factual accuracy, escalation quality, access discipline, client receipt, and reviewer effort answer different questions. One serious authority breach can justify narrowing the pilot even when average completion is high. Conversely, a small number of correctly surfaced exceptions may show that the control works. Record the accounts and tasks proposed for the next cohort, the evidence that supports expansion, the unresolved risks, and the date of the next gate. That produces a decision trail rather than a retrospective claim that the pilot felt successful.`],
'client-onboarding-stalled-dependency-recovery':[
`Use a dependency map when onboarding stalls. In the example, the team can review documentation and practice in a sandbox, but it cannot validate production permissions or confirm a live reporting workflow. Mark those facts separately. The client contact's absence explains the delay but does not authorize another employee to share credentials or approve access. Identify an alternate authorized system owner, the exact request they need to decide, and the consequence of waiting. Then tell the client which preparation can continue and which launch claim remains unavailable. This preserves useful momentum without disguising a production blocker as routine progress.`,
`When access arrives, do not simply restore the original calendar. Test the granted role against the approved request, confirm the correct account population is visible, and run a controlled sample. Recalculate training, shadow review, and first-client-update dates from that evidence. If a downstream meeting must move, route the revised date through the person who owns the client commitment. Close the recovery record only after the blocked milestone passes its acceptance test and any temporary workaround is removed. The lesson for the next onboarding is specific: name backup approvers and access lead times before a single absence can stop the critical path.`],
'account-portfolio-segmentation-rules':[
`A useful portfolio view can keep commercial importance, service risk, and workload separate. For example, renewal value may place one account in a senior review lane, while an unresolved access incident places a smaller account in the urgent operational queue. Combining both into a single red-amber-green score hides why attention is needed. Define the data source and refresh cadence for each dimension, then show the resulting action: contact cadence, evidence review, escalation, or owner decision. Accounts with missing inputs belong in an unknown lane with a recovery task; they should not inherit an average score.`,
`Test the rules against actual capacity before publishing them. If forty accounts qualify for weekly review but the approved team can examine only twenty, the model has produced a queue rather than a plan. Decide which consequence breaks ties, who may override the order, how long an override lasts, and what evidence is retained. Sample accounts near every threshold to find abrupt or unfair results. At the next review, compare predicted attention with real exceptions and client commitments. Change definitions prospectively and preserve prior classifications, allowing managers to explain why an account moved without rewriting its history.`],
'renewal-contact-authority-confirmation':[
`Build a contact-authority table before renewal material is circulated. One column identifies people permitted to receive operational performance evidence; another identifies commercial participants, procurement reviewers, notice recipients, and signatories. Attach a source to every assignment, such as the governing agreement, a current written instruction from an authorized contact, or an approved internal legal interpretation. A CRM title or a person's participation in earlier calls may prompt a question, but it should not silently confer authority. Where evidence conflicts, narrow distribution and ask the qualified owner to resolve it.`,
`In the example, the familiar stakeholder can still coordinate the meeting while the procurement owner reviews commercial material. The account specialist prepares the performance record, logs recipient questions, and schedules the next step, but does not disclose pricing or interpret signature authority without approval. If the client reorganizes, preserve the prior authority record with an end date and create a new effective record rather than overwriting history. Before a formal notice or offer is sent, verify the channel, recipient, version, and delivery evidence. This separates a productive relationship from a legally or commercially consequential decision.`],
'qbr-action-decision-trace':[
`During a quarterly review, capture the language that changes obligations. “We should explore automation” creates research work; “approve the proposed workflow for the stated account set” may create implementation work; “we will decide after security review” creates a dependency. Put the evidence, speaker, conditions, and decision authority beside each statement. The note taker should not upgrade enthusiasm into approval. When the meaning is uncertain, send a focused confirmation that quotes the disputed item and offers bounded choices instead of circulating a broad recap that embeds an assumption.`,
`Carry each confirmed item into an action trace with a preparation owner, decision owner, due event, evidence of completion, and client update. A task can be complete while the decision remains open, and a decision can be recorded while implementation is still pending. Preserve those states. At the following account review, reconcile the trace against source systems and sent communications rather than copying old bullets forward. If a later condition invalidates the decision, record the superseding event and its effect. The result is a history that explains both what the client agreed and what the team actually did.`],
'crm-duplicate-account-merge-control':[
`Before merging two CRM accounts, compare authoritative identifiers, billing or contract references, domains, addresses, ownership, and current client confirmation where appropriate. Similar names can represent a parent, subsidiary, reseller, or unrelated organization. Inventory contacts, open opportunities, service cases, consent or preference records, activities, custom objects, integrations, and automation triggers on both candidates. Choose the survivor based on an approved identity rule, not whichever record looks cleaner. For every conflicting field, name the source and decision owner; do not let the merge tool's default precedence make a business decision.`,
`After approval, preserve the permitted rollback evidence and execute during a controlled window. Verify more than the new account screen. Check report totals, relationship links, opportunity ownership, ticket history, notification recipients, synchronization logs, and any workflow keyed to the retired identifier. Search for the old identifier in downstream systems and route residual references. Tell affected operators which record now controls and how to report a discrepancy. Close only when tests pass and exceptions have owners. This procedure protects history while preventing a duplicate from continuing to fragment future account work.`],
'client-response-coverage-schedule':[
`Design coverage from demand evidence and owner availability. Map each approved channel by local time, request type, typical volume, and the decision roles reachable during that window. Define acknowledgement as confirmation that the request was captured; triage as classification and evidence gathering; resolution as the authorized outcome. These are not interchangeable promises. A Philippines-based specialist may acknowledge a commercial request and prepare its context while the commercial owner is offline, then provide a specific next-update time. Security, safety, or privacy events should follow their dedicated urgent path rather than the ordinary account queue.`,
`Test handoffs at the edges: a request arriving five minutes before shift end, a client using an unmonitored personal channel, a holiday mismatch, and an outage in the primary queue. Each case needs a visible owner and client-safe wording. Measure missed acknowledgements, reassignment delay, stale waiting items, and updates sent without enough evidence. If demand clusters outside the planned window, adjust staffing or expectations through an approved change; do not encourage hidden overtime. Publish the final schedule with its timezone, channels, exclusions, and escalation route so “coverage” has an observable meaning.`],
'account-manager-leave-coverage-plan':[
`Start temporary coverage with obligations that fall inside the absence. For each affected account, list scheduled client contacts, open commitments, renewal or reporting cutoffs, known risks, and decisions expected. Give the temporary owner only the records and permissions needed for those tasks. A copied mailbox or unrestricted portfolio export can expose unrelated information without improving continuity. Separate client-facing facts from private personnel notes, and name the permanent decision owner for commercial or exceptional questions. Rehearse one routine update and one escalation before the leave begins.`,
`During coverage, the substitute records every new promise, correction, client response, and pending decision in the normal account system. Avoid creating a parallel notebook that disappears at handback. On return, the primary manager and substitute reconcile the change log, confirm client follow-ups, transfer open items, and identify anything that needs owner review. Remove temporary groups, forwarding, and shared links from their source systems, then verify removal rather than relying on a closed ticket. A short after-action note can improve future coverage without turning an individual absence into a performance judgment.`],
'client-complaint-acknowledgement-playbook':[
`An acknowledgement should show that the complaint was heard and controlled. Preserve the client's wording, channel, time, affected service, and immediate consequence. Respond with empathy for the reported experience, but do not assert an unverified cause, accept liability, or promise a credit. State which evidence is being checked, who owns the next response, and when the next update will arrive. If service continuity, safety, security, or privacy may be affected, activate the relevant specialist route immediately rather than waiting for the ordinary complaint review.`,
`The investigation record should connect the complaint to activity logs, commitments, prior updates, and the defined service expectation. Include contrary evidence and distinguish an isolated miss from a repeated pattern. The account specialist can assemble this record and keep the client updated; qualified owners decide contractual meaning, remedy, and legal wording. The final response should address the reported impact, confirmed findings, approved correction, remaining uncertainty, and follow-up date. Capture client receipt and any disagreement. Close corrective actions separately so sending a response cannot be mistaken for fixing the underlying process.`],
'service-credit-request-routing':[
`Treat a credit request as a controlled commercial decision. Record the client's exact request and affected period, then assemble delivery records, incident findings, earlier commitments, invoices, and the governing agreement source for qualified review. A spreadsheet can calculate a provisional amount under stated assumptions, but it cannot decide eligibility or authorize an offer. Mark provisional figures accordingly and restrict them to approved reviewers. The acknowledgement should confirm receipt and the next decision update without admitting fault or promising a result before the evidence and authority are complete.`,
`Route the packet to the named commercial owner and any required legal, finance, or service reviewer. Track questions about population, dates, calculation basis, tax treatment, invoice application, and client wording as separate dependencies. Once a decision is approved, send only the approved version through the agreed channel and retain delivery evidence. Verify downstream execution in the billing or finance system and reconcile it with the account record. If no credit is approved, preserve the reason and any corrective service work. Closing the commercial request must not hide an operational issue that still needs action.`],
'client-account-offboarding-closure-checklist':[
`Build the offboarding inventory from the approved end condition and the systems actually used. Include open client questions, promised deliverables, commercial items, retained records, shared files, CRM ownership, support queues, integrations, scheduled reports, credentials, groups, and automated messages. Decide whether each item is delivered, transferred, retained under policy, revoked, stopped, or assigned as residual work. Do not delete evidence needed for contractual, legal, security, or business retention, and do not keep broad access merely because removal is inconvenient.`,
`Sequence the work so transfer and verification precede irreversible closure. Provide the client an approved summary of delivered materials, remaining obligations, contact routing, and effective dates. Then test access removal from the source systems, confirm scheduled jobs and messages have stopped, and search for integrations that use service identities rather than named users. Reconcile final account notes and ownership so later questions have an accountable destination. The closure record should identify the evidence for every disposition and a reopen path for a missed dependency; an end date alone is not proof of a controlled exit.`],
'account-review-data-cutoff-reconciliation':[
`Freeze the review population, source versions, timezone, and cutoff before narrative approval. When a late support export changes an open-item count, log the affected records and recalculate every dependent measure. Determine whether the change is a late event, a correction to the reporting period, a definition change, or a source failure. Apply the approved correction and materiality rule consistently. A favorable late record should not be accepted while an unfavorable one is deferred. Preserve the earlier deck and label the controlling version rather than silently replacing a file reviewers may already have opened.`,
`Choose the response based on decision impact. A nonmaterial item may enter a dated addendum; a change that alters a conclusion, commitment, or client decision may require reapproval or a postponed review. During the meeting, say which results are through the cutoff and identify later events separately. Afterward, reconcile the delivered deck, recording, recap, source query, and next-period opening balance. Assign any source-quality correction to an owner. This approach lets account reporting remain timely without pretending changing operational data was static or allowing a last-minute refresh to rewrite the period.`],
};
const independent:Record<string,{headings:string[];paragraphs:string[]}>= {
'outsourced-account-management-pilot-scorecard':{headings:['Decide what the pilot must prove','Freeze the test cohort','Count accepted work, not activity','Expose invisible manager effort','Treat exceptions as evidence','Set an expansion gate','Choose the next bounded cohort','Record the pilot decision'],paragraphs:[
`A pilot is useful only when leaders agree what decision it will inform. Write the approved task boundary, account count, review period, baseline, and reasons the business might expand, extend, narrow, or stop. Separate service measures from safeguards: quick follow-up does not excuse an unsupported promise, while a correctly escalated exception is not a productivity failure. Name the reviewer before work starts and preserve the initial criteria so the team cannot redefine success after seeing the results.`,
`Select accounts that represent the intended work without quietly loading the sample with easy cases. Include ordinary follow-up, one account with incomplete data, one approaching a client commitment, and a case likely to test an approval boundary. Record exclusions and why they were excluded. Freeze the cohort and task list for the decision window. New urgent work can still be handled, but it belongs in a separately labelled exception rather than changing the denominator used to judge the pilot.`,
`Track each output through prepared, reviewed, returned, accepted, sent, and verified states. A draft produced on time but returned for a wrong source should not count like accepted work. Capture correction reason, reviewer time, and whether instructions were clear. This distinguishes training needs from a broken handoff. It also prevents a high volume of drafts from masking the work required to make them safe enough for a client. Use account-level examples beside aggregate measures.`,
`Manager effort is part of the operating cost. Record time spent clarifying scope, finding sources, rewriting messages, resolving access, and making owner-only decisions. Some oversight is expected during a pilot, so the goal is not zero involvement. The useful question is whether effort falls as instructions improve and whether remaining review concentrates on decisions that should stay with the owner. Hidden rescue work can make an unsafe workflow appear efficient; visible coaching can show a viable role becoming stable.`]},
'client-onboarding-stalled-dependency-recovery':{headings:['Locate the first true blocker','Separate preparation from launch','Find the authorized resolver','Offer only safe parallel work','Recalculate dates from evidence','Validate the recovered path','Remove temporary workarounds','Learn from the stalled launch'],paragraphs:[
`Start at the earliest milestone that cannot satisfy its acceptance test. “Waiting on access” is too broad: name the workspace, requested role, business purpose, approver, request time, and test that remains impossible. Trace which later milestones genuinely depend on that result. Training attendance may continue while production validation cannot. This prevents a long checklist from making the launch look almost complete when one unresolved dependency controls every meaningful next step.`,
`Build two lanes. The preparation lane may include approved documentation, sandbox exercises, sample records, role review, and questions for the returning contact. The launch lane contains production actions that require live access, authoritative data, or client approval. Label outputs from the first lane as preparation rather than readiness proof. A sandbox success cannot establish production permissions, integrations, or population. This distinction lets the team use waiting time without turning provisional evidence into a promise.`,
`Identify who can resolve the dependency from the client’s approved authority record or system ownership, not from convenience. An alternate contact may coordinate the request yet lack permission to approve access. Send a concise packet containing the original request, purpose, minimum role, affected milestone, elapsed time, and exact decision needed. Avoid forwarding an entire conversation. If nobody with authority is reachable, record that limitation and the next check rather than borrowing access or sharing another user’s credentials.`,
`When the blocker clears, verify the grant from the source system and run the acceptance test that was previously impossible. Check account population, permitted actions, audit trail, and removal date for any temporary role. Then rebuild the schedule from the verified event. Preserve the earlier dates as superseded targets and route changed client commitments to their owners. Recovery is complete only when downstream work uses the corrected plan and the workaround lane no longer carries production activity.`]},
'account-portfolio-segmentation-rules':{headings:['Name the decision segmentation changes','Keep value, risk, and work separate','Define every input and cutoff','Protect unknown accounts','Test threshold edge cases','Fit the model to capacity','Control overrides','Explain every movement'],paragraphs:[
`A segmentation rule should change a specific action: review cadence, contact coverage, evidence depth, escalation route, or owner attention. Begin with that action and its consequence. A label such as strategic or tier one is not useful unless an operator can tell what to do differently. Write separate purposes when commercial importance and service risk lead to different actions. This avoids a single ranking that appears precise but cannot explain why one account receives attention before another.`,
`Maintain distinct dimensions for renewal timing, unresolved commitments, service exceptions, stakeholder change, data confidence, and approved commercial importance. Each dimension needs a definition, source, cutoff, refresh event, and owner. Do not average unlike signals merely to create one score. A small account with a serious unresolved security question may need urgent operational attention while a large stable account needs senior relationship review. Both can be true without forcing either into a universal red category.`,
`Unknown is a real state. Missing activity history, an inaccessible contract record, or a contact change awaiting confirmation must not become zero risk. Create a recovery action and state which decisions remain unsafe until the evidence returns. Compare conclusions under a conservative assumption so managers can see whether missingness matters. If half the portfolio lacks a required field, the immediate finding concerns data readiness, not the apparent distribution of healthy and unhealthy accounts.`,
`Run the proposed rules against available reviewer hours. If the model assigns weekly review to more accounts than the team can examine, specify a tie-break based on consequence and due events rather than hidden judgment. Test accounts immediately above and below each threshold and document surprising outcomes. Overrides require a reason, approver, effective period, and expiry review. Preserve prior classifications so a later manager can distinguish changing evidence from a rewritten definition.`]},
'renewal-contact-authority-confirmation':{headings:['Separate relationship from authority','Map four renewal roles','Attach evidence to each role','Resolve conflicting records','Limit commercial distribution','Handle organizational change','Verify the formal route','Close with a dated authority view'],paragraphs:[
`A familiar stakeholder may know the account well and still lack authority to receive pricing, change terms, issue notice, or sign. Build the renewal contact view around decisions rather than seniority. Distinguish operational coordination, commercial discussion, procurement review, formal notice, and signature. The same person may hold several roles, but each assignment needs evidence. This protects the relationship by asking a precise authority question instead of challenging the person’s importance to the account.`,
`Use the governing agreement, current authorized instruction, procurement record, and qualified internal interpretation as evidence sources. CRM titles, old meeting attendance, and historical behavior can trigger review but should not establish consequential rights by themselves. Record the source date, scope, channel, and any limit. Where two records conflict, preserve both and pause only the affected action. Scheduling a meeting can continue while pricing distribution or formal notice waits for resolution.`,
`Prepare different recipient lists for performance evidence, exploratory questions, commercial offers, and formal notices. Apply data minimization to each packet. The account specialist may compile facts and coordinate timing, while pricing, terms, contract interpretation, and signature reliance stay with authorized owners. Before sending, verify the recipient, document version, approved wording, channel, and delivery evidence. A useful checklist makes accidental over-distribution harder without preventing ordinary operational contact.`,
`Reorganizations require effective dating rather than overwriting. End the old role, preserve actions valid under it, record the new authority source, and review open renewal work for reassignment. Check scheduled messages and shared folders as well as the CRM contact field. Close the authority confirmation with unresolved conflicts, approved recipients, formal route, and next reconfirmation trigger. The outcome is not a claim about legal power; it is a traceable operational view for qualified owners to use.`]},
'qbr-action-decision-trace':{headings:['Listen for decision language','Link discussion to evidence','Preserve conditions and dissent','Separate decisions from actions','Confirm ambiguous wording','Track superseding events','Reconcile at the next review','Show what actually changed'],paragraphs:[
`Quarterly reviews contain observations, ideas, preferences, requests, decisions, and commitments. Capture the words that distinguish them. “Explore automation” authorizes investigation, while “approve this workflow for these accounts” may authorize bounded implementation. Record the speaker, evidence referenced, conditions, affected scope, and apparent authority. Do not let a polished recap upgrade interest into approval. If the statement matters and its status is unclear, mark it open before assigning irreversible work.`,
`Give every agenda item a trace from source evidence through discussion to the recorded outcome. Preserve contrary figures and questions raised during the meeting. A decision can be valid with conditions; a discussion can be useful without reaching a decision. Include a no-decision state with the evidence or owner still required. This keeps teams from filling silence with the outcome they expected and lets the next reviewer understand why a task did or did not begin.`,
`Actions need preparation owners, decision owners, due events, acceptance evidence, and a client update. Completion of research does not complete the decision; approval does not complete implementation. Keep those states distinct. When a condition changes, record whether the action pauses, narrows, or returns for approval. Link the superseding event instead of editing the earlier minute. A reliable trace explains the sequence without pretending everyone knew the final answer at the original meeting.`,
`Send a focused confirmation for material ambiguity. Quote the item, state the team’s bounded interpretation, list the action it would trigger, and offer a clear correction route. Avoid asking the client to approve an entire recap merely to settle one consequential sentence. At the next account review, reconcile every open trace against source systems and sent communications. The reader should be able to see what was discussed, decided, acted on, accepted, or superseded.`]},
'crm-duplicate-account-merge-control':{headings:['Prove the records describe one account','Choose an authoritative survivor','Decide fields individually','Map relationships and automations','Preserve a permitted rollback','Test downstream consequences','Route residual references','Close without erasing history'],paragraphs:[
`Similar names do not prove identity. Compare authoritative organization identifiers, agreement references, approved domains, addresses, ownership, and current confirmation where appropriate. A parent, subsidiary, reseller, and unrelated company can share words in their names. Record match evidence and contradictions before selecting a survivor. If the evidence cannot resolve identity, keep the records separate and route the question. A premature merge can mix contacts, permissions, opportunities, and service histories in ways that are difficult to reverse.`,
`Choose the surviving account using an approved identity rule, then decide precedence field by field. Recent is not always authoritative. A newer informal note should not replace an agreement identifier, while a current confirmed contact can supersede an old directory entry. For each conflict, record both values, sources, effective dates, and decision owner. Do not let the merge tool’s default setting make a business decision merely because it can complete the operation quickly.`,
`Inventory linked contacts, cases, opportunities, activities, files, consent or preference records, custom objects, reports, integrations, external identifiers, and workflow triggers. Identify which links will move automatically and which require controlled correction. Preserve a permitted rollback record under the applicable retention rule. Schedule the merge when reviewers can test it and dependent teams can avoid simultaneous changes. Notify only operators who need the new controlling identifier.`,
`After execution, test operational use rather than only the account page. Reconcile report totals, search results, ownership, case history, notification recipients, synchronization logs, and automations keyed to the retired identifier. Search downstream systems for remaining references and assign each exception. Confirm that the retired record cannot silently receive new work. Closure preserves the identity decision, field choices, change evidence, tests, and residual queue so history remains understandable.`]},
'client-response-coverage-schedule':{headings:['Map demand by channel and time','Define five response states','Match decisions to reachable owners','Design the shift-edge handoff','Plan outages and holidays','Test realistic requests','Measure hidden waiting','Publish honest expectations'],paragraphs:[
`Coverage begins with observed demand, not an “always available” promise. Map approved channels, client timezones, arrival patterns, request classes, and the roles available in each window. Separate routine coordination from commercial, technical, privacy, security, or safety decisions. A Philippines-based support shift may overlap part of the client day and still provide strong continuity when the next owner and update time are explicit. The map should reveal gaps rather than conceal them behind a broad availability label.`,
`Define acknowledgement, capture, triage, owner assignment, progress update, and resolution. An acknowledgement confirms receipt; it does not promise a fix. Triage records consequence and evidence; it does not make an owner-only decision. For every class, state what the support role may say, which information it gathers, and who decides next. Use a dedicated urgent route for security, privacy, safety, or severe continuity events instead of stretching the ordinary account queue.`,
`Design the handoff for a request arriving near shift end. The outgoing operator records the source, client effect, evidence gathered, pending decision, responsible owner, and next promised update. The receiving owner acknowledges the handoff in the system rather than relying on forwarded chat. Include holiday mismatches, channel outages, unmonitored personal messages, and unavailable decision owners in exercises. Each case needs client-safe wording that states what is known and when the next check occurs.`,
`Measure missed acknowledgements, reassignment delay, waiting without a dated update, reopened routing, and updates sent without sufficient evidence. Review whether demand clusters outside the planned window and whether staff use hidden overtime to protect an unrealistic schedule. Adjust staffing or client expectations through an approved change. Publish the final timezone, channels, coverage windows, exclusions, urgent route, and meaning of each response target so clients and operators interpret the schedule consistently.`]},
'account-manager-leave-coverage-plan':{headings:['Scope the absence window','Inventory obligations, not inboxes','Assign temporary and permanent owners','Grant only task-matched access','Rehearse routine and exception paths','Record changes during coverage','Run a two-person handback','Remove temporary dependencies'],paragraphs:[
`Start with obligations that fall inside the absence: client meetings, promised updates, renewal or reporting cutoffs, open risks, and expected decisions. Do not copy an entire mailbox or portfolio simply because it is easier than selecting relevant work. For each account, identify essential contacts, current commitments, approved wording, source records, and what can wait. The plan should protect continuity without spreading unrelated client information or private personnel notes.`,
`Name the temporary work owner and the permanent decision owner. The substitute may prepare reports, coordinate meetings, and send approved routine updates, while commercial, legal, security, privacy, and exceptional scope choices remain with an authorized owner. Grant only the systems and records needed for the covered work, with start and expiry conditions. Record who approved access and how removal will be verified after the handback.`,
`Rehearse one normal client update and one escalation before leave begins. The substitute should locate the authoritative record, explain the next action, and reach the correct decision owner without private coaching. Fix missing context in the normal account system rather than a temporary notebook. Tell affected clients only the approved continuity information they need, including the contact route and timing, without disclosing personal details about the absence.`,
`During coverage, record new commitments, corrections, decisions, and client responses where the primary manager will find them. At return, both managers reconcile the change log, open work, sent messages, and unresolved questions. Transfer ownership deliberately; do not assume the returning person noticed every update. Remove forwarding, groups, shared links, and temporary roles in their source systems, then verify the result. Preserve a short improvement note focused on the coverage process.`]},
'client-complaint-acknowledgement-playbook':{headings:['Preserve the complaint as received','Acknowledge impact without guessing','Separate continuity from investigation','Set the next truthful checkpoint','Build an evidence record','Route remedy decisions','Answer with findings and limits','Close response and correction separately'],paragraphs:[
`Capture the client’s wording, channel, time, affected service, requested outcome, and immediate consequence. Do not smooth a strong statement into a generic “feedback” label or add a cause the client did not assert. Link the account and service record while access is controlled. If the message suggests safety, security, privacy, or serious continuity risk, activate the relevant urgent route immediately; the ordinary complaint review can continue alongside that protective action.`,
`An acknowledgement should demonstrate listening and control. Recognize the reported experience, state what evidence is being checked, name the response owner, and give a realistic update time. Avoid admitting an unverified cause, accepting liability, or promising a credit or other remedy. If the final answer cannot be ready at the checkpoint, promise an update rather than an outcome. This keeps communication moving without creating a second complaint from an unsupported commitment.`,
`Build the investigation record from activity logs, client commitments, prior updates, service definitions, and relevant owner decisions. Use a declared cutoff and include contrary evidence. Distinguish one missed update from a repeated pattern, and distinguish restoration from explanation. The account specialist may assemble facts and maintain the communication rhythm, while qualified owners interpret agreements, legal exposure, remedy, and material process change.`,
`The final response should address reported impact, confirmed findings, uncertainty, approved correction, any authorized remedy, and the next review. Record delivery and client receipt, including disagreement. Keep response closure separate from corrective-action closure: sending a careful message does not repair a workflow, and completing a process change does not prove the client received an answer. Reopen the complaint when new evidence changes a material finding or an agreed action fails.`]},
'service-credit-request-routing':{headings:['Capture the request without accepting it','Freeze the affected period','Assemble evidence and agreement sources','Separate arithmetic from eligibility','Control provisional figures','Coordinate required reviewers','Verify the approved disposition','Keep service correction visible'],paragraphs:[
`Record the client’s exact request, channel, affected service, period, stated impact, and requested timing. A request is not approval, and acknowledgement is not acceptance of fault. Tell the client who owns the decision and when the next update will arrive. Preserve prior communications and avoid paraphrasing a monetary request into a concession the client did not ask for. If service is still impaired, route continuity work separately from the commercial decision.`,
`Assemble delivery records, incident findings, open commitments, invoices, and the governing agreement source for qualified review. Mark the evidence cutoff and any inaccessible source. The account specialist can organize this packet but should not interpret contract language. If records disagree about the affected population or period, present the conflict and its calculation effect rather than choosing the value that produces the simplest answer.`,
`A spreadsheet may calculate scenarios under stated assumptions, but arithmetic does not establish eligibility or authorize an offer. Label every provisional figure, calculation basis, included invoices, tax treatment question, and rounding rule. Limit distribution to approved reviewers. Commercial, finance, legal, and service owners may have separate decisions; track their dependencies so the account update explains what is pending without exposing internal debate or implying approval.`,
`Once authorized, send only the approved wording and amount through the agreed channel and retain delivery evidence. Verify execution in the billing or finance system and reconcile it with the account record. If the request is declined, preserve the approved reason and client response. Keep operational corrective work open until its own evidence is complete. Closing the credit decision must not hide a service problem, and repairing service must not silently decide the commercial request.`]},
'client-account-offboarding-closure-checklist':{headings:['Translate the end condition','Inventory obligations and records','Plan transfer before revocation','Apply retention and minimization','Stop automations and routing','Verify access in source systems','Send the approved closure summary','Assign every residual item'],paragraphs:[
`Begin with the approved end condition: contract event, completed transition, client instruction, or another authorized decision. Translate it into effective dates and operational consequences without interpreting ambiguous terms yourself. Inventory open client questions, promised deliverables, commercial items, retained records, CRM ownership, support queues, shared files, integrations, scheduled reports, identities, groups, and automated messages. An end date is a trigger for controlled work, not proof that the account is closed.`,
`Decide whether each item is delivered, transferred, retained, revoked, stopped, deleted under policy, or assigned as residual work. Name the accountable owner and evidence. Transfer required records before removing the access needed to perform that transfer, but do not keep broad convenience access indefinitely. Qualified legal, privacy, security, finance, and contract owners decide retention and disputed obligations. The account specialist coordinates the inventory and confirms approved actions.`,
`Test more than named user access. Review service identities, API connections, shared links, distribution lists, report schedules, workflow rules, inbox routing, and cached exports. Confirm removals and stops from source systems. Preserve audit history required for accountability while separating it from current operational access. Search for messages or tasks still capable of reaching the former client route and assign any dependency that cannot close on the effective date.`,
`Provide an approved client summary of delivered material, transfer locations, remaining obligations, contact routing, and effective dates. Do not expose internal security or personnel detail. Reconcile the final account note with sent evidence and assign later questions to a durable owner. Close only when every inventory item has a disposition and proof or a named residual owner. Maintain a reopen path for a missed dependency, retention correction, or client evidence received later.`]},
'account-review-data-cutoff-reconciliation':{headings:['Freeze the reporting boundary','Classify every late change','Apply one correction rule','Trace effects into narrative','Choose addendum, reapproval, or delay','Control the meeting version','Reconcile next-period opening data','Improve the source refresh'],paragraphs:[
`Before narrative approval, freeze the account population, source versions, query or export time, timezone, and cutoff. Record which systems were unavailable and which late events belong after the period. This creates a reproducible boundary for the review. Without it, a dashboard refresh can change figures while the deck, spoken explanation, and client decisions continue to rely on different states. The cutoff is not a claim that operations stopped; it tells readers which evidence the report covers.`,
`Classify a new record as a late event, correction to the reporting period, definition change, duplicate, or source failure. Log the affected measures and narrative claims. Apply the same materiality and correction rule whether the change improves or worsens the story. Preserve the earlier version and its approval history. Do not silently replace a deck that reviewers may already have opened, because later readers need to understand what was known at each decision point.`,
`Choose the response from consequence. A nonmaterial correction may fit a dated addendum. A change that reverses a conclusion, alters a commitment, or affects a client decision may require reapproval or postponement. Name the owner of that choice. During the meeting, distinguish results through the cutoff from later operational events. If figures remain under review, state the uncertainty and next checkpoint instead of selecting an unsupported number to keep the agenda moving.`,
`After delivery, reconcile the deck, source query, meeting recording, recap, and next-period opening balance. Confirm which version the client received and whether a correction must be sent. Assign source-quality work separately from report closure. Review refresh timing, handoffs, and approval lead time so the next cycle receives usable data earlier. The outcome is a traceable account review whose numbers and narrative share one boundary without pretending that live operational data was static.`]}
};
const sources=[{name:'NIST Cybersecurity Framework 2.0',date:'February 26, 2024',url:'https://www.nist.gov/cyberframework',note:'Governance and review vocabulary; it is not an account-performance benchmark.'},{name:'ISO quality management principles',date:'accessed October 2, 2026',url:'https://www.iso.org/quality-management/principles',note:'Process, evidence-based decision, and improvement principles.'},{name:'NIST accountability glossary',date:'accessed October 2, 2026',url:'https://csrc.nist.gov/glossary/term/accountability',note:'Traceable responsibility vocabulary.'}];
function build(topic:Topic):RichArticle{const [slug,title,service,purpose,fields,opening,image]=topic.core;const content=independent[slug];const paragraphs=[topic.analysis,deepDive[slug][0],...content.paragraphs,deepDive[slug][1],topic.closing];return {title:`Philippines account management ${title.toLowerCase()}`,description:`An October 2, 2026 field guide to ${purpose}.`,published:'2026-10-02',updated:'2026-10-02',readMinutes:17,heroImage:`/blog-heroes/${image}`,intro:[`Published October 2, 2026. ${opening}`,topic.situation,`The working record covers ${fields}.`],takeaways:['Define the decision before collecting evidence.','Keep facts, interpretation, and authority separate.','Test an ordinary case and a difficult exception.','Close with proof, residual ownership, and a reopen rule.'],sections:content.headings.map((heading,index)=>({heading,paragraphs:[paragraphs[index]]})),banners:[{label:'Related service',title:'Keep ownership visible',body:'Use approved sources and named decision owners.',href:`/services/${service}`,link:'See related support'},{label:'Reporting',title:'Preserve the evidence trail',body:'Make limits and corrections visible.',href:'/services/account-reporting',link:'See reporting support'},{label:'Next step',title:'Start with a bounded workflow',body:'Test the routine before expanding it.',href:'/contact-us',link:'Contact Us'}],table:{caption:`${title} decision record`,headers:['Field','Record'],rows:[['Purpose',purpose],['Evidence',fields],['Boundary','Owner-only decisions remain with authorized owners'],['Closure','Verified result, residual item, and reopen rule']]},chart:[{label:'Source',value:100,color:'#e8c98e'},{label:'Decision',value:72,color:'#b9dfce'},{label:'Proof',value:46,color:'#ffd9ce'}],chartMeta:{title:`${title} review path`,desc:'An illustrative path from source to decision and proof.',heading:'Source, decision, proof',method:'Illustrative workflow, not measured performance.'},quote:{text:'Accountability allows actions to be traced to an entity.',source:'NIST accountability glossary',url:'https://csrc.nist.gov/glossary/term/accountability'},script:[`We reviewed ${title.toLowerCase()} against [source] on [date]. The confirmed fact is [fact], and [owner] is deciding [open point].`,'The next approved update is due [date]. Closure requires [proof], with [owner] retaining any residual item.'],faqs:[{q:`What belongs in this ${title.toLowerCase()}?`,a:`Record ${fields}, the client consequence, authority boundary, and closure proof.`},{q:'Who decides sensitive issues?',a:'Authorized owners retain commercial, legal, security, privacy, access, and scope decisions.'},{q:'When should the record reopen?',a:'Reopen when evidence changes, approval expires, acceptance fails, or the client corrects a material fact.'}],sources};}
export const october2BlogPosts=topics.map(topic=>({slug:`philippines-account-management-${topic.core[0]}`,title:`Philippines account management ${topic.core[1].toLowerCase()}`,published:'2026-10-02' as const,excerpt:`An October 2, 2026 guide to ${topic.core[3]}.`,minutes:15}));
export const october2RichArticles:Array<[string,RichArticle]>=topics.map(topic=>[`philippines-account-management-${topic.core[0]}`,build(topic)]);
